<?php
declare(strict_types=1);
final class TransferService {
 public static function create(PDO $p,array $d,int $user):array{$from=(int)($d['from_warehouse_id']??0);$to=(int)($d['to_warehouse_id']??0);if(!$from||!$to||$from===$to)throw new DomainException('Choose two different warehouses.');$lines=$d['lines']??[];$key=(string)($d['idempotency_key']??'');if(!$lines||!preg_match('/^[a-f0-9-]{16,64}$/i',$key))throw new DomainException('Transfer lines and a valid idempotency key are required.');$p->beginTransaction();try{$q=$p->prepare('SELECT transfer_no FROM transfers WHERE idempotency_key=?');$q->execute([$key]);if($old=$q->fetchColumn()){$p->commit();return ['transfer_no'=>$old,'duplicate'=>true];}$q=$p->prepare('SELECT id FROM warehouses WHERE id IN (?,?) AND is_active=1 ORDER BY id FOR UPDATE');$q->execute([$from,$to]);if($q->rowCount()!==2)throw new DomainException('Both warehouses must be active.');$clean=[];foreach($lines as $l){$b=positive_int($l['batch_id']??null,'lines.batch_id');$n=positive_int($l['quantity']??null,'lines.quantity');$clean[$b]=($clean[$b]??0)+$n;}ksort($clean);foreach($clean as $b=>$n){$q=$p->prepare('SELECT expiration_date FROM batches WHERE id=? FOR UPDATE');$q->execute([$b]);$expiry=$q->fetchColumn();if(!$expiry)throw new DomainException("Batch $b does not exist.");if($expiry<date('Y-m-d'))throw new DomainException("Batch $b is expired.");$q=$p->prepare('SELECT quantity FROM stock_levels WHERE batch_id=? AND warehouse_id=? FOR UPDATE');$q->execute([$b,$from]);$available=(int)($q->fetchColumn()?:0);if($n>$available)throw new DomainException("Only $available units of batch $b are available at source.");}$year=date('Y');$seq=(int)$p->query("SELECT COUNT(*) FROM transfers WHERE YEAR(created_at)=$year")->fetchColumn()+1;$no=sprintf('TR-%s-%04d',$year,$seq);$p->prepare('INSERT INTO transfers(transfer_no,from_warehouse_id,to_warehouse_id,notes,idempotency_key,user_id) VALUES(?,?,?,?,?,?)')->execute([$no,$from,$to,trim((string)($d['notes']??'')),$key,$user]);$id=(int)$p->lastInsertId();foreach($clean as $b=>$n){InventoryService::move($p,(int)$b,$from,-$n,'transfer_out','Transfer '.$no,$user,$no);InventoryService::move($p,(int)$b,$to,$n,'transfer_in','Transfer '.$no,$user,$no);$p->prepare('INSERT INTO transfer_lines(transfer_id,batch_id,quantity) VALUES(?,?,?)')->execute([$id,$b,$n]);}$p->commit();return ['transfer_no'=>$no,'duplicate'=>false];}catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}}
}
